import {escapeHTML as esc,formatTime,icon} from './ui.js';

const $=id=>document.getElementById(id);
const sourceLabels={drive:'Google Drive',github:'GitHub'};
const dateLabel=value=>{const date=new Date(value);return Number.isFinite(date.getTime())?new Intl.DateTimeFormat('es-MX',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'America/Tijuana'}).format(date):'Sin fecha de guardado';};
const safeMedia=value=>typeof value==='string'&&(/^(?:https?:\/\/|blob:|data:image\/|\.?\.?\/|\/)/i.test(value)||/^[a-zA-Z0-9_-]+\//.test(value))?value:'';
const sourceFor=(provider,url,name='')=>{
 const value=new URL(String(url).trim());const host=value.hostname.toLowerCase();
 if(value.protocol!=='https:'||value.username||value.password||(provider==='drive'?!['drive.google.com','docs.google.com'].includes(host):host!=='github.com'))throw Error(provider==='drive'?'Pega un enlace HTTPS de Google Drive.':'Pega un enlace HTTPS de github.com a un repositorio o carpeta.');
 return {provider,url:value.href,name:String(name).trim().slice(0,160)||sourceLabels[provider]};
};

/** Projects are supplied by the app; this module never fakes a provider connection. */
export function mountProjects(hooks){
 const home=document.createElement('main');home.id='projectsHome';home.className='projects-home-page';home.hidden=true;home.setAttribute('aria-labelledby','projectsHeading');
 home.innerHTML=`<div class="projects-container"><header class="projects-intro"><div><span class="eyebrow">TU ESPACIO DE VIDEO</span><h1 id="projectsHeading">Mis proyectos<span>.</span></h1><p>Un proyecto por video. Guarda tus avances y vuelve a editar cuando quieras.</p></div><button class="button gold projects-upload-primary" type="button" id="homeUploadVideoBtn">${icon('plus')} Subir un video</button></header>
 <section class="project-start-options" aria-label="Empezar otro proyecto"><button type="button" class="project-start-card" id="homeVideoTile"><span class="project-start-icon">${icon('media')}</span><span><strong>Subir un video</strong><small>Hasta 50 MB · celular o computadora</small></span><span class="project-start-arrow">↗</span></button><button type="button" class="project-start-card" id="homeDriveBtn"><span class="project-start-icon drive">${icon('reference')}</span><span><strong>Google Drive</strong><small>Vincula una carpeta de materiales</small></span><span class="project-start-arrow">↗</span></button><button type="button" class="project-start-card" id="homeGithubBtn"><span class="project-start-icon github">${icon('layers')}</span><span><strong>GitHub</strong><small>Vincula un repositorio o una carpeta</small></span><span class="project-start-arrow">↗</span></button></section>
 <div class="projects-external-actions"><button type="button" id="homeOpenDriveBtn">Abrir mi Drive ↗</button><button type="button" id="homeOpenGithubBtn">Abrir GitHub ↗</button><label for="homeImportProjectInput">${icon('upload')} Importar proyecto editable<input type="file" id="homeImportProjectInput" accept=".json,application/json" hidden></label></div>
 <section class="projects-library" aria-label="Proyectos guardados"><div class="projects-library-heading"><div><h2>Tus videos <span id="homeProjectCount">0</span></h2><p id="projectsLibraryStatus" role="status">Cargando tus proyectos…</p></div><div class="projects-library-controls"><label class="projects-search">${icon('search')}<input id="projectSearchInput" type="search" placeholder="Buscar un proyecto" aria-label="Buscar proyecto"></label><button type="button" id="refreshProjectsBtn" class="icon-btn outlined" aria-label="Actualizar proyectos" title="Actualizar proyectos">${icon('reset')}</button></div></div><div id="projectCards" class="project-cards" aria-live="polite"></div></section>
 <footer class="projects-footer"><span>${icon('lock')} Tu biblioteca privada de Legacy Studio</span><p>Abre un proyecto para pedir cambios por texto o voz.</p></footer></div><input type="file" id="homeUploadVideoInput" accept="video/*,.mp4,.mov,.webm,.m4v" hidden>`;
 document.querySelector('.topbar').after(home);
 const homeButton=document.createElement('button');homeButton.type='button';homeButton.id='homeProjectsBtn';homeButton.className='button project-home-button';homeButton.innerHTML=`${icon('grid')}<span>Inicio</span>`;homeButton.setAttribute('aria-label','Ir al inicio de proyectos');
 const saveButton=document.createElement('button');saveButton.type='button';saveButton.id='saveProjectBtn';saveButton.className='button project-save-button';saveButton.innerHTML=`${icon('check')}<span>Guardar</span>`;saveButton.setAttribute('aria-label','Guardar este proyecto');
 const actions=document.querySelector('.top-actions');actions.prepend(saveButton);actions.prepend(homeButton);document.body.classList.add('has-project-library');
 const sourceDialog=document.createElement('dialog');sourceDialog.id='projectSourceDialog';sourceDialog.className='project-source-dialog';sourceDialog.setAttribute('aria-labelledby','projectSourceHeading');
 sourceDialog.innerHTML=`<form id="projectSourceForm"><button type="button" id="projectSourceCloseBtn" class="project-source-close" aria-label="Cerrar">${icon('close')}</button><span class="eyebrow" id="projectSourceEyebrow">MATERIALES DEL PROYECTO</span><h2 id="projectSourceHeading">Vincular una carpeta</h2><p id="projectSourceDescription"></p><label class="field">Nombre de la fuente<input id="projectSourceName" type="text" maxlength="160" placeholder="Ej. Materiales de mi nuevo video"></label><label class="field" id="projectSourceURLField">Enlace de la carpeta o proyecto<input id="projectSourceURL" type="url" required placeholder="https://" autocomplete="off"></label><div class="project-source-note"><span>✦</span><p>El enlace queda guardado como fuente. Después, envía la solicitud desde <b>Cambios con IA</b> para que tu ChatGPT importe los materiales. Puedes subir aquí un video o un proyecto editable si ya lo descargaste.</p></div><p class="project-source-error" id="projectSourceError" role="alert" hidden></p><button type="submit" id="prepareSourceProjectBtn" class="button gold full">Preparar proyecto con esta fuente</button><button type="button" id="linkSourceToCurrentBtn" class="button full subtle">Vincular al proyecto actual</button><button type="button" id="openSourceOutsideBtn" class="project-source-external">Abrir Google Drive ↗</button></form>`;
 document.body.append(sourceDialog);
 let projects=[],visible=false,loading=false,sourceProvider='drive',disposed=false,operation=false,refreshNumber=0,isSaving=false;
 const notify=(message,type='info')=>hooks.notify?.(message,type,8000);
 const external=url=>window.open(url,'_blank','noopener,noreferrer');
 function setSaving(saving,message){isSaving=saving;saveButton.disabled=saving;saveButton.classList.toggle('is-saving',saving);saveButton.querySelector('span').textContent=message||(saving?'Guardando…':'Guardar');saveButton.setAttribute('aria-label',message||(saving?'Guardando proyecto':'Guardar este proyecto'));}
 async function runOperation(work,{openEditor=false}={}){
  if(operation)return;operation=true;home.setAttribute('aria-busy','true');
  try{const result=await work();if(openEditor){hideHome();hooks.onEditor?.();}else await refresh();return result;}
  catch(error){notify(error.message||'No se pudo completar la operación.','error');}
  finally{operation=false;home.removeAttribute('aria-busy');$('homeUploadVideoInput').value='';$('homeImportProjectInput').value='';}
 }
 function renderCards(){
  const query=$('projectSearchInput').value.trim().toLowerCase(),filtered=projects.filter(p=>`${p.title||''} ${(p.sources||[]).map(s=>s.name||sourceLabels[s.type||s.provider]||'').join(' ')}`.toLowerCase().includes(query));
  $('homeProjectCount').textContent=projects.length;
  $('projectCards').innerHTML=filtered.length?filtered.map(p=>{
   const thumbnail=safeMedia(p.thumbnail||p.coverURL||p.cover),cloud=p.storage==='cloud'||p.savedInCloud===true,localNewer=p.localNewer===true||p.unsynced===true;
   return `<article class="project-card"><button type="button" class="project-card-open" data-open-project="${esc(p.id)}" aria-label="Abrir ${esc(p.title||'Proyecto sin nombre')}"><div class="project-card-cover ${thumbnail?'':'no-cover'}">${thumbnail?`<img src="${esc(thumbnail)}" alt="" loading="lazy">`:`<span>${icon('play')}</span>`}<span class="project-card-format">${p.width&&p.height?esc(p.width+' × '+p.height):'VIDEO'}</span>${p.duration?`<span class="project-card-duration">${formatTime(p.duration)}</span>`:''}<span class="project-card-play">${icon('play')}</span></div><div class="project-card-info"><span class="project-card-kicker">${p.version?esc(p.version):'PROYECTO DE VIDEO'}</span><h3>${esc(p.title||'Proyecto sin nombre')}</h3><p>${p.sceneCount?`${p.sceneCount} escena${p.sceneCount===1?'':'s'} · `:''}${esc(dateLabel(p.updatedAt))}</p><div class="project-card-tags"><span class="project-storage ${cloud&&!localNewer?'cloud':''}">${icon(cloud&&!localNewer?'check':'history')}${localNewer?'Cambios locales pendientes':cloud?'Guardado en tu espacio privado':'En este dispositivo'}</span>${(p.sources||[]).slice(0,2).map(s=>`<span>${esc(sourceLabels[s.type||s.provider]||s.name||'Fuente vinculada')}</span>`).join('')}</div></div><span class="project-card-action">Abrir proyecto <span>→</span></span></button></article>`;
  }).join(''):`<div class="projects-empty"><span>${icon(query?'search':'media')}</span><h3>${query?'No encontramos ese proyecto':'Tu próximo video empieza aquí'}</h3><p>${query?'Prueba con otro nombre o borra la búsqueda.':'Sube un video o importa un proyecto editable para empezar.'}</p>${query?'':'<button class="button gold" type="button" id="emptyUploadVideoBtn">Subir un video</button>'}</div>`;
  home.querySelectorAll('[data-open-project]').forEach(button=>button.addEventListener('click',()=>runOperation(()=>hooks.openProject(button.dataset.openProject),{openEditor:true})));
  $('emptyUploadVideoBtn')?.addEventListener('click',pickVideo);
 }
 async function refresh(){
  if(disposed)return;const number=++refreshNumber;loading=true;$('refreshProjectsBtn').disabled=true;$('projectsLibraryStatus').textContent='Cargando tus proyectos…';
  try{const result=await hooks.listProjects();if(disposed||number!==refreshNumber)return;projects=Array.isArray(result)?result:result.projects||[];projects.sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||'')));renderCards();$('projectsLibraryStatus').textContent=result.offline?'Sin conexión. Mostrando las copias de este dispositivo.':projects.some(p=>p.storage==='device'||p.storage==='local')?'Tus copias locales y los proyectos de tu espacio privado.':'Guardados para volver a trabajar en ellos.';}
  catch(error){if(number!==refreshNumber)return;$('projectsLibraryStatus').textContent='No se pudo actualizar la biblioteca.';if(!projects.length)$('projectCards').innerHTML='<div class="projects-empty"><h3>No pudimos cargar tus proyectos</h3><p>Actualiza la biblioteca para volver a intentarlo. Tu proyecto abierto sigue disponible.</p></div>';notify(error.message,'error');}
  finally{if(number===refreshNumber){loading=false;$('refreshProjectsBtn').disabled=false;}}
 }
 async function showHome(){
  if(operation)return;await hooks.beforeHome?.();visible=true;home.hidden=false;document.body.classList.add('projects-home');document.querySelector('.project-menu')?.setAttribute('hidden','');homeButton.setAttribute('aria-current','page');await refresh();
 }
 function hideHome(){visible=false;home.hidden=true;document.body.classList.remove('projects-home');homeButton.removeAttribute('aria-current');}
 function pickVideo(){if(!operation)$('homeUploadVideoInput').click();}
 function openSource(provider){
  sourceProvider=provider;const p=hooks.getProject?.(),existing=p?.sources?.find(s=>(s.type||s.provider)===provider);$('projectSourceForm').reset();$('projectSourceName').value=existing?.name||'';$('projectSourceURL').value=existing?.url||'';$('projectSourceError').hidden=true;$('projectSourceHeading').textContent=provider==='drive'?'Materiales de Google Drive':'Materiales de GitHub';$('projectSourceDescription').textContent=provider==='drive'?'Vincula la carpeta donde están tu video y sus materiales para retomarlos con ChatGPT.':'Vincula el repositorio o la carpeta que contiene el video, su código y los recursos editables.';$('projectSourceURL').placeholder=provider==='drive'?'https://drive.google.com/drive/folders/…':'https://github.com/usuario/repositorio/tree/main/carpeta';$('linkSourceToCurrentBtn').hidden=!p;$('linkSourceToCurrentBtn').textContent=p?'Vincular a '+(p.title||'este proyecto'):'Vincular al proyecto actual';$('openSourceOutsideBtn').textContent=provider==='drive'?'Abrir mi Drive ↗':'Abrir GitHub ↗';sourceDialog.showModal();
 }
 function currentSource(){return sourceFor(sourceProvider,$('projectSourceURL').value,$('projectSourceName').value);}
 async function submitSource(linkCurrent){
  if(operation)return;if(!$('projectSourceForm').reportValidity())return;
  let source;try{source=currentSource();}catch(error){$('projectSourceError').textContent=error.message;$('projectSourceError').hidden=false;return;}
  operation=true;$('prepareSourceProjectBtn').disabled=true;$('linkSourceToCurrentBtn').disabled=true;$('projectSourceError').hidden=true;
  try{if(linkCurrent){await hooks.linkSource({...source,projectId:hooks.getProject()?.id});sourceDialog.close();await refresh();notify('Fuente vinculada al proyecto.');}else{if(!hooks.importSource)throw Error('Primero abre un proyecto para vincular esta fuente.');await hooks.importSource(source);sourceDialog.close();hideHome();hooks.onEditor?.();}}
  catch(error){$('projectSourceError').textContent=error.message||'No se pudo vincular esta fuente.';$('projectSourceError').hidden=false;}
  finally{operation=false;$('prepareSourceProjectBtn').disabled=false;$('linkSourceToCurrentBtn').disabled=false;}
 }
 const safeHome=()=>showHome().catch(error=>notify(error.message,'error'));homeButton.onclick=safeHome;saveButton.onclick=async()=>{if(operation)return;setSaving(true);try{await hooks.saveProject();notify('Proyecto guardado.','success');if(visible)await refresh();}catch(error){notify(error.message,'error');}finally{setSaving(false);}};
 $('homeUploadVideoBtn').onclick=pickVideo;$('homeVideoTile').onclick=pickVideo;$('homeDriveBtn').onclick=()=>openSource('drive');$('homeGithubBtn').onclick=()=>openSource('github');$('homeOpenDriveBtn').onclick=()=>external('https://drive.google.com/drive/u/0/my-drive');$('homeOpenGithubBtn').onclick=()=>external('https://github.com/');$('refreshProjectsBtn').onclick=refresh;$('projectSearchInput').oninput=renderCards;
 $('homeUploadVideoInput').onchange=e=>{const file=e.target.files?.[0];if(file)runOperation(()=>hooks.uploadVideo(file),{openEditor:true});};$('homeImportProjectInput').onchange=e=>{const file=e.target.files?.[0];if(file)runOperation(()=>hooks.importProject(file),{openEditor:true});};
 $('projectSourceForm').onsubmit=e=>{e.preventDefault();submitSource(false);};$('linkSourceToCurrentBtn').onclick=()=>submitSource(true);$('projectSourceCloseBtn').onclick=()=>{if(!operation)sourceDialog.close();};sourceDialog.addEventListener('cancel',e=>{if(operation)e.preventDefault();});$('openSourceOutsideBtn').onclick=()=>{let url=sourceProvider==='drive'?'https://drive.google.com/drive/u/0/my-drive':'https://github.com/';if($('projectSourceURL').value.trim()){try{url=currentSource().url;}catch(error){$('projectSourceError').textContent=error.message;$('projectSourceError').hidden=false;return;}}external(url);};
 const brand=document.querySelector('.studio-brand'),brandClick=e=>{e.preventDefault();safeHome();};brand?.addEventListener('click',brandClick);
 function refreshContext(){const p=hooks.getProject?.();saveButton.disabled=isSaving||!p;}
 refreshContext();
 return {showHome,hideHome,refresh,setSaving,refreshContext,get visible(){return visible;},get loading(){return loading;},openSource,dispose(){disposed=true;brand?.removeEventListener('click',brandClick);home.remove();homeButton.remove();saveButton.remove();sourceDialog.remove();document.body.classList.remove('has-project-library','projects-home');}};
}
